1	package main
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"os"
8		"strings"
9	
10		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
11	)
12	
13	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
14	type replicateInput struct {
15		CurrentTerm    int                      `json:"currentTerm"`
16		CommittedIndex int                      `json:"committedIndex"`
17		Log            []mevwatch.LogEntry      `json:"log"`
18		ApplyKV        bool                     `json:"applyKV"`
19		Requests       []mevwatch.AppendRequest `json:"requests"`
20	}
21	
22	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
23	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
24	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
25	func runReplicate() int {
26		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
27	}
28	
29	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
30		data, err := io.ReadAll(stdin)
31		if err != nil {
32			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
33			return 1
34		}
35		var raw interface{}
36		if err := json.Unmarshal(data, &raw); err != nil {
37			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
38			return 1
39		}
40		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
41		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
42		// 输入阶段把整份输入作为字段类型错误拒绝。
43		if path := nullNumericFieldPath(raw); path != "" {
44			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
45			return 1
46		}
47		var input replicateInput
48		if err := json.Unmarshal(data, &input); err != nil {
49			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
50			return 1
51		}
52		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
53			CurrentTerm:    input.CurrentTerm,
54			CommittedIndex: input.CommittedIndex,
55			Log:            input.Log,
56		}, input.Requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
57		if err != nil {
58			fmt.Fprintf(stderr, "replicate: %v\n", err)
59			return 1
60		}
61		encoded, err := json.MarshalIndent(output, "", "  ")
62		if err != nil {
63			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
64			return 1
65		}
66		fmt.Fprintln(stdout, string(encoded))
67		return 0
68	}
69	
70	// nullNumericFieldPath 在已解析的输入 JSON 中查找第一个被显式写成 null 的
71	// 已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始状态
72	// （currentTerm、committedIndex、log[i].index、log[i].term）与每条复制请求
73	// （term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
74	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
75	// requests[1].leaderCommit。字段名识别与 encoding/json 一致，只改变字母
76	// 大小写的写法同样命中。数组字段本身与未知键里的 null 沿用既有处理，不在
77	// 检查范围内。
78	func nullNumericFieldPath(raw interface{}) string {
79		root, ok := raw.(map[string]interface{})
80		if !ok {
81			return ""
82		}
83		for _, name := range []string{"currentTerm", "committedIndex"} {
84			if hasExplicitNull(root, name) {
85				return name
86			}
87		}
88		if entries, ok := lookupArray(root, "log"); ok {
89			for i, entry := range entries {
90				if path := nullEntryFieldPath(entry, fmt.Sprintf("log[%d]", i)); path != "" {
91					return path
92				}
93			}
94		}
95		if requests, ok := lookupArray(root, "requests"); ok {
96			for i, request := range requests {
97				obj, ok := request.(map[string]interface{})
98				if !ok {
99					continue
100				}
101				prefix := fmt.Sprintf("requests[%d]", i)
102				for _, name := range []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"} {
103					if hasExplicitNull(obj, name) {
104						return prefix + "." + name
105					}
106				}
107				if entries, ok := lookupArray(obj, "entries"); ok {
108					for j, entry := range entries {
109						if path := nullEntryFieldPath(entry, fmt.Sprintf("%s.entries[%d]", prefix, j)); path != "" {
110							return path
111						}
112					}
113				}
114			}
115		}
116		return ""
117	}
