119	// nullEntryFieldPath 检查一条日志条目（初始日志或请求条目）的 index 与 term
120	// 是否被显式写成 null，返回带 prefix 的完整位置；条目不是对象或没有 null
121	// 数值字段时返回空串。
122	func nullEntryFieldPath(entry interface{}, prefix string) string {
