135	// hasExplicitNull 报告对象中按 encoding/json 的字段名识别规则（大小写不敏感）
136	// 命中 name 的键是否被显式写成 null。
137	func hasExplicitNull(obj map[string]interface{}, name string) bool {
138		for key, value := range obj {
139			if strings.EqualFold(key, name) && value == nil {
140				return true
141			}
