214	// TestCLIStaleTermTakesPriorityOverConflictHint 端到端锁定低任期请求的优先级：
215	// 即使前置日志同时不匹配（本地 idx1 任期 1，请求声称 2），也按低任期拒绝、
216	// 维持原任期 5，且输出中完全没有 conflict 字段——不是输出 null，也不误给
217	// 重发建议。日志、提交位置与键值表全部保持原样。
218	func TestCLIStaleTermTakesPriorityOverConflictHint(t *testing.T) {
219		input := `{
220		  "currentTerm": 5,
221		  "committedIndex": 1,
222		  "log": [
223		    {"index": 1, "term": 1, "command": "set x=1"}
224		  ],
225		  "applyKV": true,
226		  "requests": [
227		    {"term": 3, "prevLogIndex": 1, "prevLogTerm": 2, "leaderCommit": 2,
228		     "entries": [{"index": 2, "term": 3, "command": "set y=2"}]}
229		  ]
230		}`
231		out, body := runReplicateRaw(t, input)
232		if len(out.Results) != 1 {
233			t.Fatalf("expected 1 result, got %+v", out.Results)
234		}
235		result := out.Results[0]
236		if result.Accepted || result.Reason != mevwatch.ReasonStaleTerm {
237			t.Fatalf("lower term must reject as stale term even with a mismatched prev log, got %+v", result)
238		}
239		if result.Conflict != nil {
240			t.Fatalf("stale-term rejection must not carry a conflict hint: %+v", result.Conflict)
241		}
242		if result.Term != 5 || result.CommittedIndex != 1 {
243			t.Fatalf("stale-term rejection must keep state, got term %d ci %d, want term 5 ci 1",
244				result.Term, result.CommittedIndex)
245		}
246		if result.AppliedIndex == nil || *result.AppliedIndex != 1 || result.ApplyError != nil {
247			t.Fatalf("result apply state = %+v %+v, want appliedIndex 1 and no error",
248				result.AppliedIndex, result.ApplyError)
249		}
250		if out.FinalTerm != 5 || out.FinalCommittedIndex != 1 || len(out.FinalLog) != 1 {
251			t.Fatalf("unexpected final state: %+v", out)
252		}
253		if len(out.FinalKV) != 1 || out.FinalKV["x"] != "1" {
254			t.Fatalf("finalKV = %v, want only x=1", out.FinalKV)
255		}
256		// 公开约定：输出中完全没有 conflict 字段（注意拒绝原因文本不含该键名，
257		// 因此按键名判断）；也绝不能出现 "conflict": null。
258		if strings.Contains(body, `"conflict"`) {
259			t.Fatalf("stale-term rejection output must not contain a conflict key at all:\n%s", body)
260		}
261		if strings.Contains(body, "set y=2") {
262			t.Fatalf("the rejected entry's command must not appear in the output:\n%s", body)
263		}
264	}
265	
266	// TestCLIConflictHintWithoutApplyKV 保留两条既有公开约定：applyKV 未开启时输出
267	// 省略全部应用字段（前置日志不匹配的 conflict 建议照常给出）；成功请求不携带
268	// conflict。同一次调用内先接受一条合法追加、再拒绝一条越界前置，逐条核对。
269	func TestCLIConflictHintWithoutApplyKV(t *testing.T) {
270		input := `{
271		  "currentTerm": 1,
272		  "committedIndex": 1,
273		  "log": [
274		    {"index": 1, "term": 1, "command": "a"}
275		  ],
276		  "requests": [
277		    {"term": 1, "prevLogIndex": 1, "prevLogTerm": 1, "leaderCommit": 2,
278		     "entries": [{"index": 2, "term": 1, "command": "b"}]},
279		    {"term": 1, "prevLogIndex": 9, "prevLogTerm": 1, "entries": [], "leaderCommit": 0}
280		  ]
281		}`
282		out, body := runReplicateRaw(t, input)
283		if len(out.Results) != 2 {
284			t.Fatalf("expected 2 results, got %+v", out.Results)
285		}
286		first := out.Results[0]
287		if !first.Accepted || first.Reason != mevwatch.ReasonOK {
288			t.Fatalf("valid append must be accepted: %+v", first)
289		}
290		if first.Conflict != nil {
291			t.Fatalf("accepted request must not carry a conflict hint: %+v", first.Conflict)
292		}
293		second := out.Results[1]
294		if second.Accepted || second.Reason != mevwatch.ReasonPrevLogMismatch {
295			t.Fatalf("expected prev-log-mismatch rejection, got %+v", second)
296		}
297		if second.Conflict == nil ||
298			*second.Conflict != (mevwatch.ConflictHint{Index: 3, Term: 0}) {
299			t.Fatalf("conflict = %+v, want {index 3, term 0} (log grew to length 2)", second.Conflict)
300		}
301		if out.FinalCommittedIndex != 2 || len(out.FinalLog) != 2 {
302			t.Fatalf("unexpected final state: %+v", out)
303		}
304		// conflict 键只在被拒绝的第二条结果里出现一次。
305		if count := strings.Count(body, `"conflict"`); count != 1 {
306			t.Fatalf("conflict key should appear exactly once (the rejected result), got %d:\n%s",
307				count, body)
308		}
309		// applyKV 未开启：整条输出不含任何应用字段。
310		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
311			if strings.Contains(body, field) {
312				t.Fatalf("applyKV disabled: output must not contain %q:\n%s", field, body)
313			}
314		}
315	}
