	}
	return out, stdout.String()
}

// TestCLIConflictHintTermMismatchApplyKV 端到端锁定前置索引存在但任期不同时的
// 拒绝答复（开启 applyKV）：本地四条日志任期依次为 1、2、2、2，已提交到 3
