func skipValue(dec *json.Decoder) {
	tok, err := dec.Token()
	if err != nil {
		return
	}
	depth := 0
	if d, ok := tok.(json.Delim); ok {
		switch d {
		case '{', '[':
			depth++
		default:
			return
